export function getProviderIcon(
  providerId: string,
  className: string = "w-full h-full",
): React.ReactNode {
  switch (providerId) {
    case "claude":
      return <ClaudeIcon className={className} />;
    case "codex":
      return <OpenAIIcon className={className} />;
    case "gemini":
      return <GeminiIcon className={className} />;
    case "antigravity":
      return <AntigravityIcon className={className} />;
    case "copilot":
      return <CopilotIcon className={className} />;
    case "qwen":
      return <QwenIcon className={className} />;
    case "kiro":
      return <KiroIcon className={className} />;
    case "vertex":
      return <VertexIcon className={className} />;
    case "iflow":
      return <IFlowIcon className={className} />;
    case "custom":
      return <CustomIcon className={className} />;
    default:
      return <CustomIcon className={className} />;
  }
}
